import { Fragment, useState } from 'react';
import { Link } from 'react-router-dom';
import { layoutCalsTable, layoutConditionDiag } from './table';
import { manualHref } from './model';
import { manualContent } from './manualContent';

// Labels generated by the original suzuki.xsl / ui.xslt for Russian.
const technical = {attention1:'ПРЕДУПРЕЖДЕНИЕ:',attention2:'ВНИМАНИЕ:',attention3:'ПРИМЕЧАНИЕ:',attention4:'УВЕДОМЛЕНИЕ:'};
const textOf = nodes => nodes.map(n=>typeof n==='string'?n:textOf(n.children)).join('').trim();
const nextElement = (nodes,i) => nodes.slice(i+1).find(n=>typeof n!=='string');
const STEP_TAGS = new Set(['s1','s2','s3']);
// Inline values keep the source line breaks around their text; trimmed, "свеча зажигания: 18 Нм" stays on one line.
const INLINE_VALUES = new Set(['t-part','t-part1','t-value1','t-note','m-part','m-desc','m-number','m-name','s-part','s-number','sdm-title','sdm-part','sdm-model','sdm-condition','sdm-value']);
const trimEdges = nodes => nodes.map((n,i)=>typeof n!=='string'?n:i===0&&i===nodes.length-1?n.trim():i===0?n.trimStart():i===nodes.length-1?n.trimEnd():n);
// Pictogram names only where the meaning is printed on the pictogram itself; otherwise the source name.
const symbolLabel = name => {
  const torque=name.match(/^MATORQUE-([A-Z])$/);
  if(torque)return `Момент затяжки (${torque[1].toLowerCase()})`;
  const product=name.match(/^MA[BL](\d{4}[A-Z]?)$/);
  if(product)return `Средство ${product[1]}`;
  return `Значок ${name}`;
};

function Illustration({node,title,labels,onOpenImage}) {
  const [failed,setFailed]=useState(false);
  const src=`${import.meta.env.BASE_URL}manual/${node.attrs.path}`;
  const caption=`${title} — ${node.attrs.graphicname.replace(/\.[^.]+$/,'')}`;
  return <span className="manual-illustration" data-source-tag="graphic">
    <button type="button" className="manual-illustration__open" onClick={()=>onOpenImage({src,caption})} aria-label={`${labels.openImage}: ${caption}`}>
      <img src={src} alt={caption} width={node.attrs.pixelWidth} height={node.attrs.pixelHeight} loading="lazy" onError={()=>setFailed(true)} />
      <span className="manual-illustration__caption">{labels.openImage}</span>
    </button>
    {failed&&<span role="status">{labels.imageError}</span>}
  </span>;
}

export default function ManualContent({document,targets,onOpenImage,labels=manualContent.ru}) {
  const renderNodes=(nodes,level=2,parent=null)=>{
    const output=[];
    for(let i=0;i<nodes.length;i++){
      const node=nodes[i];
      if(typeof node==='string'){output.push(node);continue;}
      if(STEP_TAGS.has(node.tag)){
        const steps=[node];let j=i+1;
        for(;j<nodes.length;j++){
          if(typeof nodes[j]==='string'&&!nodes[j].trim())continue;
          if(nodes[j].tag===node.tag)steps.push(nodes[j]);else break;
        }
        output.push(<ol className={`manual-steps manual-steps--${node.tag}`} key={`steps-${i}`}>{steps.map((s,k)=><li key={s.attrs.id||k} id={s.attrs.id}>{renderNodes(s.children,level)}</li>)}</ol>);i=j-1;continue;
      }
      if(node.tag==='result'){
        let j=i+1;while(typeof nodes[j]==='string'&&!nodes[j].trim())j++;
        const action=nodes[j]?.tag==='action'?nodes[j]:null;
        output.push(<div key={i} className="manual-outcome"><strong data-source-tag="result">{node.attrs.type==='yes'?'Да':'Нет'}</strong>{action&&<div data-source-tag="action">{renderNodes(action.children,level)}</div>}</div>);
        if(action)i=j;continue;
      }
      // suzuki.xsl: t-part ends with ": " unless a (t-part1) marker follows it.
      if(node.tag==='t-part'){output.push(<span key={i}>{renderNodes(trimEdges(node.children),level)}{nextElement(nodes,i)?.tag==='t-part1'?' ':': '}</span>);continue;}
      output.push(<Fragment key={node.attrs.id||i}>{renderNode(node,level,parent)}</Fragment>);
    }
    return output;
  };
  const renderNode=(node,level,parent)=>{
    const {tag,attrs,children}=node;
    const rendered=()=>renderNodes(INLINE_VALUES.has(tag)?trimEdges(children):children,level,node);
    if(tag==='title'){const H=`h${Math.min(level,5)}`;return <H id={attrs.id}>{rendered()}</H>;}
    if(tag==='ptxt'){
      if(parent?.tag==='sdm1'||parent?.tag==='sdm2')return <span> ({rendered()})</span>;
      if(parent?.tag==='materialitem'||parent?.tag==='torqueitem')return <span> {rendered()}</span>;
      return <p>{rendered()}</p>;
    }
    if(tag==='emph')return attrs.etype==='bold'?<strong>{rendered()}</strong>:<em>{rendered()}</em>;
    if(tag==='sub')return <sub>{rendered()}</sub>;
    if(tag==='sup')return <sup>{rendered()}</sup>;
    if(tag==='servinfosub')return <section id={attrs.id}>{rendered()}</section>;
    if(tag==='topic'||tag==='subtopic')return <section id={attrs.id} className={`manual-${tag}`}>{renderNodes(children,level+1,node)}</section>;
    if(tag==='paragroup')return <div id={attrs.id}>{rendered()}</div>;
    if(technical[tag])return <aside className={`manual-attention manual-attention--${tag}`}><strong>{technical[tag]}</strong>{rendered()}</aside>;
    if(tag==='list1')return attrs.type==='ordered'?<ol>{rendered()}</ol>:<ul>{rendered()}</ul>;
    if(tag==='list2'||tag==='list3')return attrs.type==='ordered'?<ol type={tag==='list2'?'a':'i'}>{rendered()}</ol>:<ul className="manual-list--dash">{rendered()}</ul>;
    if(tag==='item')return <li id={attrs.id}>{rendered()}</li>;
    if(tag==='figure'||tag==='testfigure')return <figure>{rendered()}</figure>;
    if(tag==='graphic')return <Illustration node={node} title={document.title} labels={labels} onOpenImage={onOpenImage}/>;
    if(tag==='callout'||tag==='callout-l')return <div className="manual-callout">{rendered()}</div>;
    if(tag==='spec')return <div className="manual-value manual-spec">{rendered()}</div>;
    if(tag==='table'){
      const group=children.find(n=>n.tag==='tgroup');const table=layoutCalsTable(group);
      return <div className="manual-table-scroll" role="region" aria-label={document.title} tabIndex={0}><table><tbody>{table.rows.map((row,i)=><tr key={i}>{row.cells.map(({node:cell,column,colSpan,rowSpan})=>{
        const Cell=row.header?'th':'td';
        return <Cell key={column} colSpan={colSpan} rowSpan={rowSpan} scope={row.header?'col':undefined} style={['center','right','left'].includes(cell.attrs.align)?{textAlign:cell.attrs.align}:undefined}>{renderNodes(cell.children,level)}</Cell>;
      })}</tr>)}</tbody></table></div>;
    }
    // suzuki.xsl: a two-column table, each term followed by its definition.
    if(tag==='deflist'){
      const items=children.filter(n=>typeof n!=='string');const rows=[];
      for(let i=0;i<items.length;i+=2)rows.push([items[i],items[i+1]]);
      return <div className="manual-table-scroll" role="region" aria-label={document.title} tabIndex={0}><table className="manual-deflist"><tbody>{rows.map(([term,def],i)=><tr key={term.attrs.id||i}>
        <th scope="row" id={term.attrs.id}>{renderNodes(term.children,level)}</th><td>{renderNodes(def.children,level,def)}</td>
      </tr>)}</tbody></table></div>;
    }
    if(tag==='diag'&&attrs.type==='condition'){
      const rows=layoutConditionDiag(node);
      return <div className="manual-table-scroll" role="region" aria-label={document.title} tabIndex={0}><table id={attrs.id} className="manual-condition-table">
        <thead><tr><th scope="col">Условие</th><th scope="col">Возможная причина</th><th scope="col">Действие</th></tr></thead>
        <tbody>{rows.map(({condition,ps,action},i)=><tr key={i}>
          {condition&&<td rowSpan={condition.rowSpan} data-source-tag="condition">{renderNodes(condition.node.children,level)}</td>}
          {ps&&<td rowSpan={ps.rowSpan} data-source-tag={ps.node?'ps':undefined}>{ps.node&&renderNodes(ps.node.children,level)}</td>}
          <td id={action.attrs.id} data-source-tag="action">{renderNodes(action.children,level)}</td>
        </tr>)}</tbody>
      </table></div>;
    }
    if(tag==='diag')return <ol className="manual-diagnostic" id={attrs.id}>{rendered()}</ol>;
    if(tag==='testgroup')return <li id={attrs.id}>{renderNodes(children,3,node)}</li>;
    if(tag==='question')return <p className="manual-question">{rendered()}</p>;
    if(tag==='test1'||tag==='action'||tag==='condition'||tag==='ps')return <div id={attrs.id}>{rendered()}</div>;
    if(tag.startsWith('intxref')){
      const [id,anchor]=attrs.refid.split('#');
      return <Link className={`manual-reference${targets[id]?.available?'':' manual-reference--outside'}`} to={manualHref(id,anchor)}>{rendered()}</Link>;
    }
    if(tag==='torque')return <div className="manual-value"><strong>Момент затяжки</strong>{rendered()}</div>;
    if(tag==='torqueitem'||tag==='servicetoolitem'||tag==='materialitem')return <div id={attrs.id}>{rendered()}</div>;
    if(tag==='servicetool')return <div className="manual-value"><strong>Специальный инструмент</strong>{rendered()}</div>;
    if(tag==='materials')return <div className="manual-value">{rendered()}</div>;
    if(tag==='t-part1')return <span>({rendered()}): </span>;
    if(tag==='t-note')return <span className="manual-numeric"> {rendered()}</span>;
    if(tag==='m-part')return <span>{rendered()}: </span>;
    if(tag==='m-desc')return <span>{rendered()} </span>;
    if(tag==='m-number')return <span> {rendered()}</span>;
    if(tag==='m-name')return <span> ({rendered()})</span>;
    if(tag==='scantool')return <section className="manual-value" id={attrs.id}>{rendered()}</section>;
    if(tag==='scantool-title')return <strong className="manual-value__title">{rendered()}</strong>;
    if(tag==='spec-sdm')return <div className="manual-value" id={attrs.id}>{rendered()}</div>;
    if(tag==='sdm-title')return <strong>{rendered()}</strong>;
    if(tag==='sdm-part')return <span> {rendered()}</span>;
    if(tag==='sdm-model')return <span> ({rendered()})</span>;
    if(tag==='sdm1')return <div>{rendered()}</div>;
    if(tag==='sdm2')return <div className="manual-sdm2">{rendered()}</div>;
    if(tag==='sdm-condition')return <span>{parent?.tag==='sdm2'&&textOf(children)?'• ':''}{rendered()}:</span>;
    if(tag==='sdm-value')return <strong className="manual-numeric"> {rendered()}</strong>;
    if(['s-part','s-number'].includes(tag))return <span>{rendered()}{' '}</span>;
    if(tag==='t-value1')return <strong className="manual-numeric">{rendered()}</strong>;
    if(tag==='button')return <span className="manual-scan-reference" title={labels.scanReference}>[Suzuki SDT-II: {attrs.code}]</span>;
    if(tag==='symbol'&&attrs.path)return <img className="manual-symbol" src={`${import.meta.env.BASE_URL}manual/${attrs.path}`} alt={symbolLabel(attrs.name)} title={symbolLabel(attrs.name)} loading="lazy"/>;
    if(tag==='symbol')return <span>{{star:'★',squf:'■',utrif:'▲',dtrif:'▼',utri:'△',dtri:'▽',rtrif:'▶'}[attrs.name]||attrs.name}</span>;
    throw new Error(`Unsupported manual display node: ${tag} ${textOf(children)}`);
  };
  return <div className="manual-content" lang="ru">{renderNodes(document.body)}</div>;
}
